"""Check actual animated vector alpha against the shared flight envelope."""
import json,shutil
from pathlib import Path
from playwright.sync_api import sync_playwright
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page();p.goto('http://127.0.0.1:8854/HONRO.html');p.wait_for_function('window.HonroMonsterVisual && window.HONRO_CORE',timeout=90000)
 rows=p.evaluate('''()=>{const rows=[],cv=document.createElement('canvas');cv.width=cv.height=512;const c=cv.getContext('2d',{willReadFrequently:true});for(const [id,h,r]of[['bat',66,28],['crow',80,33]])for(const facing of[-1,1])for(let i=0;i<16;i++)for(const state of[{}, {move:true}, {attack:i/15}, {hit:i/15}]){c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,512,512);c.translate(256,350);c.scale(h/100*facing,h/100);HonroMonsterVisual.draw(c,id,{time:i*.137,state,pixels:200,detail:2});const d=c.getImageData(0,0,512,512).data;let left=512,right=0,head=512,feet=0;for(let y=0;y<512;y++)for(let x=0;x<512;x++)if(d[(y*512+x)*4+3]>16){left=Math.min(left,x);right=Math.max(right,x+1);head=Math.min(head,y);feet=Math.max(feet,y+1);}const actual={left:left-256,right:right-256,head:head-350,feet:feet-350},safe=HONRO_CORE.flightBounds({h,r,honroType:id},{x:0,y:0});if(actual.left<safe.left-1||actual.right>safe.right+1||actual.head<safe.head-1||actual.feet>safe.feet+1)throw Error(JSON.stringify({id,i,state,actual,safe}));rows.push({id,facing,i,state,actual,safe});}return rows;}''')
 out=Path('_local/reports/airborne-clearance');out.mkdir(parents=True,exist_ok=True);(out/'visual-alpha.json').write_text(json.dumps({'scope':__doc__,'samples':len(rows),'rows':rows},indent=2));print('PASS actual vector alpha inside flight envelope:',len(rows),'poses');b.close()
